	path = "[{0}]_types_/{1}".format(p,u)
#	query = root.getAlarmTags(u)
#	results = system.tag.query(p, query)
	results = system.tag.browse(path, {"tagType":"AtomicTag"} )
	ds = []
	# Regex explanation:
	# (/[^/]+/[^/_]+)  -> Captures / followed by characters, another /, and then the ID (FBKR01)
	# (_SP|_VARSP|_VCMD|_CMD|_VSIG|_MODE|SEC_DP_MODE)$ -> Matches only if it ends in your list
	pattern = re.compile(r'.*(FB|VFB)$')   # adjust suffix as needed
	for r in results:
		rp = str(r["fullPath"])
		j = {}
		if re.search(pattern,rp) != None:
			if "alarm" in r['attributes']:
				config = system.tag.getConfiguration(rp)
				for c in config:
					ids = []
					alarms = c['alarms']
					alms = {}
					alms['tagpath'] = rp
					for a in alarms:
						# Setpoint A
					    ids.append({
					        'label': "{} SP".format(a['name']),
					        'value': a.get('setpointA', 0)
					    })

					    # Active Delay
					    ids.append({
					        'label': "{} Active Delay".format(a['name']),
					        'value': a.get('timeOnDelaySeconds', 0)
					    })

					    # Clear Delay (Fixed the typo from timeOn to timeOff!)
					    ids.append({
					        'label': "{} Clear Delay".format(a['name']),
					        'value': a.get('timeOffDelaySeconds', 0)
					    })

					alms['alarms'] = ids
					ds.append(alms)
return ds

